// Des: Read command line words into one Args struct
// Flo: walk argv > flags (with or without a value) > up to 3 plain words (command, sub, extra) > safety checks
// I/O: argv slice (caller) > Args; error BadUsage on unknown flag, missing value, or --force without --live
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig");
const VALS = [_][]const u8{ "--text", "--to", "--url", "--title", "--price", "--desc", "--group", "--photo", "--opt", "--date", "--time", "--catg", "--cond", "--loca" };
pub const CMDS = [_][]const u8{ "help", "version", "status", "caps", "ledger", "log", "jobs", "pause", "resume", "unlock", "plan", "approve", "deny", "flow", "login", "setup", "doctor", "snap", "read", "map", "gaps", "secret", "start", "report", "backup", "export", "purge", "run", "ask" };
pub const Args = struct { cmdz: []const u8 = "", subz: []const u8 = "", extr: []const u8 = "", json: bool = false, dryz: bool = false, live: bool = false, forc: bool = false, read: bool = false, head: bool = false, helz: bool = false, yesz: bool = false, conf: []const u8 = "", acct: []const u8 = "", tsk: task.Args = .{}, sink: ?*std.ArrayList(u8) = null,
pub fn known(self: Args) bool { for (CMDS) |nam| { if (std.mem.eql(u8, nam, self.cmdz)) return true; } return false; }
pub fn writes(self: Args) bool { if (std.mem.eql(u8, self.cmdz, "flow")) return std.mem.eql(u8, self.subz, "run"); for ([_][]const u8{ "run", "ask", "start", "setup" }) |nam| { if (std.mem.eql(u8, nam, self.cmdz)) return true; } return false; }
pub fn quiet(self: Args) bool { return std.mem.eql(u8, self.cmdz, "status"); }
pub fn mode(self: Args) task.Mode { if (self.read) return .read; if (self.forc) return .force; if (self.live) return .live; return .dry; } };
fn badz(what: []const u8, toke: []const u8) error{BadUsage} { std.debug.print("usage error: {s} {s}\n", .{ what, toke }); return error.BadUsage; }
pub fn argsRead(argv: []const []const u8) !Args { var args: Args = .{}; var indx: usize = 0; while (indx < argv.len) : (indx += 1) { const item = argv[indx]; if (std.mem.eql(u8, item, "--json")) { args.json = true; continue; } if (std.mem.eql(u8, item, "--live")) { args.live = true; continue; } if (std.mem.eql(u8, item, "--force")) { args.forc = true; continue; } if (std.mem.eql(u8, item, "--read")) { args.read = true; continue; } if (std.mem.eql(u8, item, "--head")) { args.head = true; continue; } if (std.mem.eql(u8, item, "--yes")) { args.yesz = true; continue; } if (std.mem.eql(u8, item, "--dry") or std.mem.eql(u8, item, "--dry-run")) { args.dryz = true; continue; } if (std.mem.eql(u8, item, "--help") or std.mem.eql(u8, item, "-h")) { args.helz = true; continue; }
if (std.mem.eql(u8, item, "--acct")) { indx += 1; if (indx >= argv.len) return badz("missing value after", item); args.acct = argv[indx]; continue; } if (std.mem.eql(u8, item, "--conf") or std.mem.eql(u8, item, "--max")) { indx += 1; if (indx >= argv.len) return badz("missing value after", item); if (item[2] == 'c') args.conf = argv[indx] else args.tsk.maxn = std.fmt.parseInt(u32, argv[indx], 10) catch return badz("not a whole number for", item); continue; } var done = false; inline for (VALS) |nam| { if (!done and std.mem.eql(u8, item, nam)) { indx += 1; if (indx >= argv.len) return badz("missing value after", item); @field(args.tsk, nam[2..]) = argv[indx]; done = true; } } if (done) continue;
if (item.len > 1 and item[0] == '-' and item[1] == '-') return badz("unknown flag", item); if (args.cmdz.len == 0) { args.cmdz = item; } else if (args.subz.len == 0) { args.subz = item; } else if (args.extr.len == 0) { args.extr = item; } else return badz("unexpected word", item); } if (args.forc and !args.live) return badz("--force needs", "--live"); if (args.read and (args.live or args.forc)) return badz("--read cannot be used with", "--live or --force"); if (args.dryz and (args.live or args.forc)) return badz("--dry-run and --live cannot be used", "together"); return args; }
